(function(){'use strict';
let previous=null;let glyphs='playstation';function validGlyph(v){return v==='xbox'||v==='playstation'}try{const stored=localStorage.getItem('ob.glyphs');if(validGlyph(stored))glyphs=stored}catch(e){}try{const supplied=window.omnibloomHost?.getGlyphs?.();if(validGlyph(supplied))glyphs=supplied}catch(e){}
function visible(e){return !e.disabled&&!e.hidden&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden'}
function items(){const d=document.querySelector('dialog[open]');return [...(d||document).querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(e=>!e.classList.contains('skip')&&visible(e))}
function focus(e){if(e){document.querySelectorAll('.pad-focus').forEach(x=>x.classList.remove('pad-focus'));e.classList.add('pad-focus');e.focus();e.scrollIntoView({block:'nearest',inline:'nearest'})}}
function move(action){const all=items(),active=document.activeElement;if(!all.length)return false;if(!all.includes(active)){focus(all[0]);return true}const r=active.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2;let best=null,score=Infinity;all.forEach(e=>{if(e===active)return;const b=e.getBoundingClientRect(),dx=b.x+b.width/2-x,dy=b.y+b.height/2-y;const primary=action==='right'?dx:action==='left'?-dx:action==='down'?dy:-dy,cross=Math.abs(action==='right'||action==='left'?dy:dx);if(primary>2){const s=primary+cross*3;if(s<score){best=e;score=s}}});if(best)focus(best);return true}
// Read-only native navigation probe; unknown/modal owners cannot emit this exact token.
function quickBoundary(){const e=document.activeElement;if(document.querySelector('dialog[open],[role=dialog][aria-modal=true]')||!items().includes(e)||e.matches('input,select,textarea')||e.isContentEditable||scrollY>1)return false;const r=e.getBoundingClientRect(),y=r.y+r.height/2;if(r.y<0||y>innerHeight/4)return false;for(let p=e.parentElement;p;p=p.parentElement)if(p.scrollTop>1)return false;return !items().some(x=>{if(x===e)return false;const b=x.getBoundingClientRect();return b.y+b.height/2<y-2})}
function handle(a){a=String(a).toLowerCase();a=({a:'cross',b:'circle',lb:'l1',rb:'r1',accept:'cross',back:'circle'})[a]||a;const e=document.activeElement;if(a==='quick-access-boundary')return quickBoundary()?'omni.quick-access.boundary':false;if(['up','down','left','right'].includes(a)){if(e&&e.matches('input[type=range]')&&['left','right'].includes(a)){a==='right'?e.stepUp():e.stepDown();e.dispatchEvent(new Event('input',{bubbles:true}));return true}if(e&&e.tagName==='SELECT'&&['left','right'].includes(a)){const n=e.options.length;e.selectedIndex=Math.max(0,Math.min(n-1,e.selectedIndex+(['right','down'].includes(a)?1:-1)));e.dispatchEvent(new Event('change',{bubbles:true}));return true}return move(a)}if(a==='cross'){if(e&&visible(e)&&e!==document.body){e.click();return true}focus(items()[0]);return true}if(a==='circle'){const d=document.querySelector('dialog[open]');if(d){d.close();focus(previous);return true}if(window.obBack)return window.obBack();return false}if(a==='l1'||a==='r1'){const tabs=[...document.querySelectorAll('[role=tab]')];if(tabs.length){const n=tabs.findIndex(t=>t.getAttribute('aria-selected')==='true'),t=tabs[(n+(a==='r1'?1:tabs.length-1))%tabs.length];t.click();focus(t);return true}return false}return false}
function glyph(){document.querySelectorAll('[data-glyph]').forEach(e=>{const key=e.dataset.glyph;e.textContent=({playstation:{accept:'×',back:'○',next:'R1',previous:'L1'},xbox:{accept:'A',back:'B',next:'RB',previous:'LB'}})[glyphs][key]||key});const b=document.querySelector('#glyph-toggle');if(b)b.textContent=glyphs==='xbox'?'Xbox glyphs':'PlayStation glyphs';document.documentElement.dataset.glyphs=glyphs}
window.obUI={handle,focus,items,openDialog(id){previous=document.activeElement;const d=document.getElementById(id);d.showModal();focus(items()[0])},toast(text){const e=document.getElementById('toast');if(e){e.textContent=text;e.hidden=false;clearTimeout(e._timer);e._timer=setTimeout(()=>e.hidden=true,5000)}}};
window.omniMediaController=handle;window.omniPadController=handle;
document.addEventListener('keydown',e=>{if(e.key==='Tab'){const a=items(),i=a.indexOf(document.activeElement);if(document.querySelector('dialog[open]')&&(e.shiftKey&&i<=0||!e.shiftKey&&i===a.length-1)){e.preventDefault();focus(e.shiftKey?a[a.length-1]:a[0])}return}if(e.target.matches('input:not([type=range]):not([type=checkbox]),textarea')){if(e.key==='Escape')e.target.blur();else return}const a={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Escape:'circle',PageDown:'r1',PageUp:'l1'}[e.key];if(a&&handle(a))e.preventDefault()});
document.addEventListener('DOMContentLoaded',()=>{document.querySelector('#glyph-toggle')?.addEventListener('click',()=>{glyphs=glyphs==='xbox'?'playstation':'xbox';try{localStorage.setItem('ob.glyphs',glyphs)}catch(e){}glyph()});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>{b.closest('dialog').close();focus(previous)}));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('cancel',e=>{e.preventDefault();d.close();focus(previous)}));glyph();focus(document.querySelector('[data-initial]')||items()[0])});
})();